import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.CkaEw-3u.js";const g=JSON.parse('{"title":"Lua API — ctx Reference","description":"ctx field reference for the Mug Typography Lua scripting API","frontmatter":{"title":"Lua API — ctx Reference","description":"ctx field reference for the Mug Typography Lua scripting API","pageClass":"reference-page scripting-api-reference","head":[["link",{"rel":"canonical","href":"https://mug-lab-3.github.io/mug-typography-docs/en/scripting/02_ctx_reference.html"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mug Typography Manual"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"property":"og:title","content":"Lua API — ctx Reference | Mug Typography Manual"}],["meta",{"property":"og:description","content":"ctx field reference for the Mug Typography Lua scripting API"}],["meta",{"property":"og:url","content":"https://mug-lab-3.github.io/mug-typography-docs/en/scripting/02_ctx_reference.html"}],["meta",{"property":"og:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"property":"og:image:type","content":"image/png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:image:alt","content":"Mug Typography Online Manual"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:site","content":"@MugLab3"}],["meta",{"name":"twitter:title","content":"Lua API — ctx Reference | Mug Typography Manual"}],["meta",{"name":"twitter:description","content":"ctx field reference for the Mug Typography Lua scripting API"}],["meta",{"name":"twitter:image","content":"https://mug-lab-3.github.io/mug-typography-docs/image/social-card.png"}],["meta",{"name":"twitter:image:alt","content":"Mug Typography Online Manual"}]]},"headers":[],"relativePath":"en/scripting/02_ctx_reference.md","filePath":"en/scripting/02_ctx_reference.md"}'),i={name:"en/scripting/02_ctx_reference.md"};function r(n,t,c,s,l,h){return d(),a("div",null,[...t[0]||(t[0]=[o('<p>Target API level: <code>5</code></p><p><code>ctx</code> is the context that Mug Typography passes to each callback. It contains the information needed to process the current frame, including the current time, canvas information, Global settings, and the generated characters and parts.</p><p>The available fields and write permissions differ by callback. This document first lists availability for each callback, then describes the fields of <code>ctx</code> in order. For the callback execution order and purposes, see <a href="./01_concepts.html#section-callback">Callback Overview</a>.</p><p><a id="section-context"></a></p><h2 id="_1-list-of-ctx-fields" tabindex="-1">1. List of <code>ctx</code> Fields <a class="header-anchor" href="#_1-list-of-ctx-fields" aria-label="Permalink to &quot;1. List of `ctx` Fields&quot;">​</a></h2><p>The fields directly under <code>ctx</code> are themselves read-only and cannot be replaced with other values. However, objects such as <code>ctx.global</code> and <code>ctx.chars[index]</code> contain fields that can be modified depending on the callback. ○ indicates that a field can be read in that callback.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th style="text-align:center;"><code>OnInitialize</code></th><th style="text-align:center;"><code>OnPreLayout</code></th><th style="text-align:center;"><code>OnLayout</code></th><th style="text-align:center;"><code>OnPath</code></th><th>Description</th></tr></thead><tbody><tr><td><code>ctx.time</code></td><td>number</td><td style="text-align:center;">—</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td>Current time in seconds, with the beginning of the clip as 0 (§1.1)</td></tr><tr><td><code>ctx.frame</code></td><td>number</td><td style="text-align:center;">—</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td>Frame number with the beginning of the clip as 0. May include subframes (§1.1)</td></tr><tr><td><code>ctx.fps</code></td><td>number</td><td style="text-align:center;">—</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td>Frame rate (§1.1)</td></tr><tr><td><code>ctx.canvas</code></td><td>table</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td>Canvas and project pixel information (§1.2)</td></tr><tr><td><code>ctx.fonts</code></td><td>string[]</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td>1-based array of font names that can be assigned to <code>global.font_name</code> (§1.3)</td></tr><tr><td><code>ctx.timeline</code></td><td>table</td><td style="text-align:center;">—</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td>Clip time range and current progress (§1.4)</td></tr><tr><td><code>ctx.font</code></td><td>table</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td>Metrics (dimensional information) for the font in use (§1.5)</td></tr><tr><td><code>ctx.text</code></td><td>string</td><td style="text-align:center;">—</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td style="text-align:center;">—</td><td>Deprecated text reference (§1.6)</td></tr><tr><td><code>ctx.char_count</code></td><td>integer</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td>Number of valid characters (§1.6)</td></tr><tr><td><code>ctx.part_count</code></td><td>integer</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td>Number of valid parts (§1.6)</td></tr><tr><td><code>ctx.meta</code></td><td>table</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td>API version and feature information (§1.7)</td></tr><tr><td><code>ctx.global</code></td><td>table</td><td style="text-align:center;">—</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td>Global settings. Writable in <code>OnPreLayout</code> and read-only thereafter (§1.8)</td></tr><tr><td><code>ctx.camera</code></td><td>table</td><td style="text-align:center;">—</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td>Camera settings. Writable in <code>OnPreLayout</code> and read-only thereafter (§1.9)</td></tr><tr><td><code>ctx.chars</code></td><td>table[]</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td>1-based array of generated characters (§1.10)</td></tr><tr><td><code>ctx.parts</code></td><td>table[]</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td>1-based array of generated parts (§1.11)</td></tr><tr><td><code>ctx.bounding_box</code></td><td>table</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td>Bounding-box drawing settings (§1.12)</td></tr><tr><td><code>ctx.output</code></td><td>table</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">○</td><td style="text-align:center;">○</td><td>Output filtering and drawing-order settings (§1.13)</td></tr><tr><td><code>ctx.paths</code></td><td>table</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">—</td><td style="text-align:center;">○</td><td>Context for retrieving and editing part paths (§1.14)</td></tr></tbody></table><p><a id="section-time"></a></p><h3 id="_1-1-ctx-time-ctx-frame-ctx-fps" tabindex="-1">1.1 <code>ctx.time</code> / <code>ctx.frame</code> / <code>ctx.fps</code> <a class="header-anchor" href="#_1-1-ctx-time-ctx-frame-ctx-fps" aria-label="Permalink to &quot;1.1 `ctx.time` / `ctx.frame` / `ctx.fps`&quot;">​</a></h3><p>These fields express the current evaluation position relative to the beginning of the clip. <code>ctx.time</code> is in seconds, and <code>ctx.frame</code> is in frames. Because <code>ctx.frame</code> can include subframes, it is not necessarily an integer. <code>ctx.fps</code> is the number of frames per 1 second.</p><p><a id="section-canvas"></a></p><h3 id="_1-2-ctx-canvas" tabindex="-1">1.2 <code>ctx.canvas</code> <a class="header-anchor" href="#_1-2-ctx-canvas" aria-label="Permalink to &quot;1.2 `ctx.canvas`&quot;">​</a></h3><p>Canvas and project pixel information. All fields are read-only.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>width</code> / <code>height</code></td><td>number</td><td>px</td><td>Canvas width and height</td></tr><tr><td><code>aspect_ratio</code></td><td>number</td><td>—</td><td>Canvas width divided by height (<code>width / height</code>)</td></tr><tr><td><code>pixel_aspect_ratio</code></td><td>number</td><td>—</td><td>Pixel aspect ratio of the host project</td></tr></tbody></table><p><a id="section-fonts"></a></p><h3 id="_1-3-ctx-fonts" tabindex="-1">1.3 <code>ctx.fonts</code> <a class="header-anchor" href="#_1-3-ctx-fonts" aria-label="Permalink to &quot;1.3 `ctx.fonts`&quot;">​</a></h3><p>A read-only, 1-based array containing the names of installed fonts recognized by the host. Its contents match the Font list in the host UI, and in <code>OnPreLayout</code> its elements can be assigned to <code>ctx.global.font_name</code>.</p><p>Neither the array elements nor the number of elements can be changed.</p><p><a id="section-timeline"></a></p><h3 id="_1-4-ctx-timeline" tabindex="-1">1.4 <code>ctx.timeline</code> <a class="header-anchor" href="#_1-4-ctx-timeline" aria-label="Permalink to &quot;1.4 `ctx.timeline`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>available</code></td><td>boolean</td><td>—</td><td>Whether a finite clip range could be obtained</td></tr><tr><td><code>start_frame</code> / <code>end_frame</code></td><td>number</td><td>frame</td><td>Start/end of the range (clip-local; the start is always 0)</td></tr><tr><td><code>duration_frames</code></td><td>number</td><td>frame</td><td><code>end_frame - start_frame</code></td></tr><tr><td><code>duration_seconds</code></td><td>number</td><td>second</td><td>Duration converted to seconds</td></tr><tr><td><code>progress</code></td><td>number</td><td>0–1</td><td>Current position clamped to 0–1</td></tr></tbody></table><h4 id="clip-range" tabindex="-1">Clip Range <a class="header-anchor" href="#clip-range" aria-label="Permalink to &quot;Clip Range&quot;">​</a></h4><p>The clip range is the clip&#39;s actual range on the timeline, including trimming and extensions before or after it. <code>ctx.time</code>, <code>ctx.frame</code>, and <code>ctx.timeline</code> receive values on the same time axis, with the beginning of the clip as 0. When applied to a video clip as a filter, they also follow that clip&#39;s range.</p><p>When <code>available</code> is <code>false</code>, the other values are 0, so provide a fallback.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Limitation of extending the beginning in generator use</strong>: When the beginning of a generator clip (with no input connected) is extended on the timeline, the host treats that interval as a still image of the first frame, so script time does not advance until the extension boundary (the intro appears frozen in its initial state). To change the duration, change the length of the generator clip itself instead of extending it. This limitation does not apply when used as a filter.</p></div><h4 id="time-axis-design-rules-anchor-×-speed" tabindex="-1">Time-Axis Design Rules (Anchor × Speed) <a class="header-anchor" href="#time-axis-design-rules-anchor-×-speed" aria-label="Permalink to &quot;Time-Axis Design Rules (Anchor × Speed)&quot;">​</a></h4><p>Animation timing is designed along 2 axes: &quot;① where it is fixed (anchor)&quot; and &quot;② how fast it advances (speed).&quot; <strong>The default speed is real seconds (based on <code>ctx.time</code>)</strong>, and <code>progress</code>, which scales proportionally with clip length, should be used only for the &quot;full-span&quot; pattern described below.</p><table tabindex="0"><thead><tr><th>Pattern</th><th>Anchor</th><th>How to Write It</th></tr></thead><tbody><tr><td>Intro (entrance)</td><td>Beginning of clip</td><td>Use <code>ctx.time</code> directly (real seconds). For a combined intro + outro, use <code>mt.timeline.intro_outro_seconds</code> (§10.9)</td></tr><tr><td>Outro (exit)</td><td>End of clip</td><td><code>mt.timeline.remaining(ctx)</code> (real seconds remaining until the end; §10.9)</td></tr><tr><td>Typewriter, stagger, spring, etc.</td><td>Beginning of clip</td><td><code>ctx.time</code> (real seconds; specify a physical speed such as ◯ seconds per 1 character)</td></tr><tr><td>Full-span pattern (drift, sweep, or reveal across the entire duration)</td><td>Entire clip</td><td><code>progress</code> (the expected behavior is for the movement to lengthen when the duration is extended)</td></tr></tbody></table><p>If a transition is written as a fraction of <code>progress</code>, extending the clip makes the fade or typing run in slow motion and breaks the intended behavior. An outro is fundamentally about aligning with the end rather than making its speed proportional to the duration, so write it in real seconds anchored to the end.</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- NG: typing speed changes when the clip length changes</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> visible </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> math.floor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(mt.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">timeline</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">progress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ctx.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">char_count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- OK: constant 0.08s per character regardless of clip length</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> visible </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> math.floor</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">time</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> /</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.08</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- OK: outro fade over the last 0.5s, anchored to the clip end</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> fade </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mt.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">clamp</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(mt.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">timeline</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">remaining</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- OK: 0.8s intro + 0.5s outro at fixed real-time speed</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- (compressed automatically only when the clip is shorter)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> intro, outro </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mt.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">timeline</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">intro_outro_seconds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><a id="section-font"></a></p><h3 id="_1-5-ctx-font-—-metrics-for-the-font-in-use" tabindex="-1">1.5 <code>ctx.font</code> — Metrics for the Font in Use <a class="header-anchor" href="#_1-5-ctx-font-—-metrics-for-the-font-in-use" aria-label="Permalink to &quot;1.5 `ctx.font` — Metrics for the Font in Use&quot;">​</a></h3><p>Metrics (dimensional information) for the font in use, resolved after layout generation.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>ascent</code></td><td>number</td><td>canvas height ratio</td><td>Ascent upward from the baseline</td></tr><tr><td><code>descent</code></td><td>number</td><td>canvas height ratio</td><td>Descent downward from the baseline (<strong>positive value</strong>, expressed as a downward amount)</td></tr><tr><td><code>line_height</code></td><td>number</td><td>canvas height ratio</td><td>Line height</td></tr><tr><td><code>units_per_em</code></td><td>number</td><td>font design unit</td><td>Number of design units in the font&#39;s em square</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>The final on-screen size can be predicted from the product of scale-related fields (2D presets only).</strong> The host internally calculates font size as a fixed ratio of <code>canvas.height</code>, so the same ratio is preserved even when the canvas resolution changes. For 2D presets, multiplying this base size by <code>character.scale × character.stretch_x/y</code>, <code>part.scale</code>, and <code>ctx.global.scale × ctx.global.stretch_x/y</code> gives the actual on-screen size (because all of these transformations are composed multiplicatively).</p><p><strong>For 3D presets, this product is only an approximation.</strong> Camera projection performs perspective division according to depth (including <code>z</code>, apparent depth changes caused by <code>yaw</code>/<code>pitch</code>, and the camera&#39;s <code>perspective</code> / <code>zoom</code>), so on-screen size changes nonlinearly with depth, and a tilted character is distorted differently at each vertex and cannot be represented by a single scale factor. <code>ctx.font</code> and <code>character.geometry</code> contain pre-projection values, and the post-projection on-screen size cannot be obtained from <code>OnLayout</code>.</p></div><p><a id="section-counts"></a></p><h3 id="_1-6-ctx-text-ctx-char-count-ctx-part-count" tabindex="-1">1.6 <code>ctx.text</code> / <code>ctx.char_count</code> / <code>ctx.part_count</code> <a class="header-anchor" href="#_1-6-ctx-text-ctx-char-count-ctx-part-count" aria-label="Permalink to &quot;1.6 `ctx.text` / `ctx.char_count` / `ctx.part_count`&quot;">​</a></h3><p><code>ctx.text</code> is deprecated. Use <code>ctx.global.text</code> to read the current text, and assign to <code>ctx.global.text</code> in <code>OnPreLayout</code> to rewrite it.</p><p><code>ctx.char_count</code> and <code>ctx.part_count</code> are the number of valid characters and parts, respectively, after layout generation. When the text or font changes, these values also change according to the shaping result.</p><p><a id="section-meta"></a></p><h3 id="_1-7-ctx-meta" tabindex="-1">1.7 <code>ctx.meta</code> <a class="header-anchor" href="#_1-7-ctx-meta" aria-label="Permalink to &quot;1.7 `ctx.meta`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>ctx.meta.api_level</code></td><td>integer</td><td>—</td><td>Lua API compatibility level</td></tr><tr><td><code>ctx.meta.plugin_version</code></td><td>string</td><td>—</td><td>Running plugin version (for display)</td></tr><tr><td><code>ctx.meta.capabilities</code></td><td>table</td><td>—</td><td>Information about currently available features. Read-only</td></tr><tr><td><code>ctx.meta.capabilities.has_3d</code></td><td>boolean</td><td>—</td><td>Whether 3D Projection is enabled for the current preset</td></tr><tr><td><code>ctx.meta.limits</code></td><td>table</td><td>—</td><td>Limits applied to this instance. Read-only</td></tr><tr><td><code>ctx.meta.limits.max_characters</code></td><td>integer</td><td>—</td><td>Maximum number of characters this instance can handle</td></tr><tr><td><code>ctx.meta.limits.max_parts</code></td><td>integer</td><td>—</td><td>Maximum number of parts this instance can handle</td></tr><tr><td><code>ctx.meta.instance_seed</code></td><td>integer</td><td>—</td><td>Stable random seed unique to this instance (between 0 and 2^31-1 inclusive). It remains the same throughout the lifetime of a given instance and differs between instances</td></tr></tbody></table><h4 id="feature-detection" tabindex="-1">Feature Detection <a class="header-anchor" href="#feature-detection" aria-label="Permalink to &quot;Feature Detection&quot;">​</a></h4><p>Determine feature availability using <code>ctx.meta.api_level &gt;= required level</code> and <code>capabilities</code>. Even when <code>has_3d</code> is <code>false</code>, assigning to Camera and yaw / pitch / z does not cause an error, but it does not affect rendering.</p><h4 id="uses-of-instance-seed" tabindex="-1">Uses of <code>instance_seed</code> <a class="header-anchor" href="#uses-of-instance-seed" aria-label="Permalink to &quot;Uses of `instance_seed`&quot;">​</a></h4><p>Using <code>instance_seed</code> as the seed for <code>mt.random</code> gives each instance a different random sequence, even with the same script.</p><p><a id="section-global"></a></p><h3 id="_1-8-ctx-global" tabindex="-1">1.8 <code>ctx.global</code> <a class="header-anchor" href="#_1-8-ctx-global" aria-label="Permalink to &quot;1.8 `ctx.global`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>text</code></td><td>string</td><td>—</td><td>UTF-8 text. Changing it reshapes the text and regenerates the character and part counts</td></tr><tr><td><code>font_name</code></td><td>string</td><td>—</td><td>Font family name (one of <code>ctx.fonts</code>). Changing it changes the font in use and reshapes the text</td></tr><tr><td><code>tracking</code></td><td>number</td><td>em</td><td>Character spacing added to the trailing advance of each character. <code>1.0</code> is 1 em</td></tr><tr><td><code>line_spacing</code></td><td>number</td><td>multiplier</td><td>Advance between lines / vertical-writing columns</td></tr><tr><td><code>vertical</code></td><td>boolean</td><td>—</td><td>When <code>true</code>, enables vertical writing and changes the shaping and placement direction</td></tr><tr><td><code>h_align</code></td><td>string</td><td>—</td><td>Horizontal alignment. <code>left</code> / <code>center</code> / <code>right</code></td></tr><tr><td><code>v_align</code></td><td>string</td><td>—</td><td>Vertical alignment. <code>top</code> / <code>center</code> / <code>bottom</code> / <code>baseline</code></td></tr><tr><td><code>margins</code></td><td>number[]</td><td>em</td><td>Trailing advance for each character. Uses the same unit as <code>tracking</code></td></tr><tr><td><code>position_x</code> / <code>position_y</code></td><td>number</td><td>canvas normalized coordinate</td><td>Global position. <code>0.5</code> is the center; positive X is right and positive Y is up</td></tr><tr><td><code>rotation</code></td><td>number</td><td>degree</td><td>Global 2D rotation. Positive (+) rotates right (clockwise); negative (-) rotates left (counterclockwise)</td></tr><tr><td><code>yaw</code> / <code>pitch</code></td><td>number</td><td>degree</td><td>Global 3D orientation. Affects rendering only in 3D presets. Positive yaw rotates the right edge toward the viewer; positive pitch rotates the top edge toward the viewer</td></tr><tr><td><code>scale</code></td><td>number</td><td>multiplier</td><td>Global uniform scale. Clamped to a minimum of <code>0.0001</code> when written</td></tr><tr><td><code>stretch_x</code> / <code>stretch_y</code></td><td>number</td><td>multiplier</td><td>Global nonuniform scale. Unlike scale, it has no positive lower bound; 0 and negative values are accepted</td></tr><tr><td><code>pivot_x</code> / <code>pivot_y</code></td><td>number</td><td><a href="./01_concepts.html#section-units">canvas normalized displacement</a></td><td>Pivot for Global transformations. <code>0.5</code> means displacement 0; larger values move it right/up from <code>global.position</code></td></tr><tr><td><code>opacity</code></td><td>number</td><td>0–1</td><td>Global opacity. The default is <code>1.0</code>. The host clamps out-of-range values to 0–1 immediately before rendering. It is multiplied as alpha after colors have been determined for fill, gradient, stroke, shadow, and bounding box (it does not participate in <code>fill.use</code> resolution. See <a href="./01_concepts.html#section-inheritance">Roles of <code>use</code> / <code>opacity</code> / <code>fill.transparent</code></a>). No corresponding keyframe parameter exists on the host; it can be written only from scripts</td></tr><tr><td><code>fill</code></td><td>table</td><td>—</td><td>Global fill settings (table below)</td></tr><tr><td><code>gradient</code></td><td>table</td><td>—</td><td>Gradient settings (table below)</td></tr><tr><td><code>stroke</code></td><td>table</td><td>—</td><td>Global stroke settings (table below)</td></tr><tr><td><code>shadow</code></td><td>table</td><td>—</td><td>Global shadow settings (table below)</td></tr></tbody></table><h4 id="ctx-global-margins" tabindex="-1"><code>ctx.global.margins</code> <a class="header-anchor" href="#ctx-global-margins" aria-label="Permalink to &quot;`ctx.global.margins`&quot;">​</a></h4><h5 id="indexing-and-calculation" tabindex="-1">Indexing and Calculation <a class="header-anchor" href="#indexing-and-calculation" aria-label="Permalink to &quot;Indexing and Calculation&quot;">​</a></h5><p><code>margins</code> is a 1-based array keyed by character number in layout order. This number is the same as the <code>index</code> later assigned in <code>ctx.chars</code>. <code>margins[i]</code> is added in em units, together with <code>tracking</code>, to the advance <strong>after</strong> the i-th character.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(margins[i] + tracking) * designUnitsPerEm</span></span></code></pre></div><h5 id="array-format" tabindex="-1">Array Format <a class="header-anchor" href="#array-format" aria-label="Permalink to &quot;Array Format&quot;">​</a></h5><p>It must be a numeric-keyed array without holes from 1 through <code>#margins</code>. Non-integer keys, string keys, holes in the middle, and non-number elements cause an error.</p><p>The default number of elements is <code>ctx.meta.limits.max_characters</code>. When assigning an entire table, a shorter dense array than the default number of elements can also be used. Elements beyond the character count do not cause an error; they are simply unused.</p><h5 id="character-count" tabindex="-1">Character Count <a class="header-anchor" href="#character-count" aria-label="Permalink to &quot;Character Count&quot;">​</a></h5><p><code>ctx.char_count</code> is undefined in <code>OnPreLayout</code>. <code>utf8.len(ctx.global.text)</code> returns the number of UTF-8 code points, which may differ from the number of characters after shaping because of combining marks, ligatures, grapheme clusters, and similar constructs. Perform operations requiring the exact count in <code>OnLayout</code>.</p><h4 id="merging-subobjects" tabindex="-1">Merging Subobjects <a class="header-anchor" href="#merging-subobjects" aria-label="Permalink to &quot;Merging Subobjects&quot;">​</a></h4><p>Assigning an entire table, as in <code>ctx.global.shadow = { enabled = true, distance = 8.0 }</code>, performs a per-field merge. Omitted fields retain their current values.</p><h4 id="ctx-global-fill" tabindex="-1"><code>ctx.global.fill</code> <a class="header-anchor" href="#ctx-global-fill" aria-label="Permalink to &quot;`ctx.global.fill`&quot;">​</a></h4><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>The <code>color</code> Type</strong></p><p><code>color</code> is a table with <code>r</code> (red), <code>g</code> (green), <code>b</code> (blue), and <code>a</code> (alpha). Each field is a number from 0–1; <code>a = 0</code> means fully transparent, and <code>a = 1</code> means fully opaque.</p><p>Fields can be assigned directly. When assigning an entire table, you can specify only the fields to change. Omitted fields retain their current values.</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ctx.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">global</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">color</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ctx.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">global</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fill</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">color</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { a </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>Fields other than <code>r</code> / <code>g</code> / <code>b</code> / <code>a</code>, and values other than numbers, cause an error.</p></div><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>color</code></td><td>color</td><td>RGBA 0–1</td><td>Global fill color. Also serves as the gradient start color</td></tr><tr><td><code>transparent</code></td><td>boolean</td><td>—</td><td>When <code>true</code>, hides the fill while preserving strokes and effects</td></tr></tbody></table><p>Characters whose <code>chars[index].fill.use</code> is <code>false</code> use <code>fill.color</code>. For the inheritance order including parts, see <a href="./01_concepts.html#section-inheritance">&quot;Inheritance Mechanism&quot;</a>.</p><h4 id="ctx-global-gradient" tabindex="-1"><code>ctx.global.gradient</code> <a class="header-anchor" href="#ctx-global-gradient" aria-label="Permalink to &quot;`ctx.global.gradient`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>color_space</code></td><td>string</td><td>—</td><td>Gradient / Crayon mode. The values are the enumeration below</td></tr><tr><td><code>end_color</code></td><td>color</td><td>RGBA 0–1</td><td>Gradient end color</td></tr><tr><td><code>midpoint</code></td><td>number</td><td>0–1</td><td>Midpoint of color interpolation</td></tr><tr><td><code>angle</code></td><td>number</td><td>degree</td><td>Gradient direction. At 0 degrees it progresses from left to right, and positive (+) rotates right (clockwise)</td></tr><tr><td><code>start_position</code> / <code>end_position</code></td><td>number</td><td>Position relative to the transformed Global bounds</td><td>Gradient interval. The standard range is 0.0–1.0. For details, see <a href="./04_appendix.html#section-gradient-coordinate-system">Gradient Range and Direction</a></td></tr></tbody></table><p>Values of <code>gradient.color_space</code>:</p><ul><li><code>none</code></li><li><code>okhsv</code></li><li><code>okhsl</code></li><li><code>oklab</code></li><li><code>linear_rgb</code></li><li><code>crayon</code></li></ul><h4 id="ctx-global-stroke" tabindex="-1"><code>ctx.global.stroke</code> <a class="header-anchor" href="#ctx-global-stroke" aria-label="Permalink to &quot;`ctx.global.stroke`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>width</code></td><td>number</td><td>em (<code>1.0</code> = font size 1 em. Multiplied by fontSize during rendering)</td><td>Stroke width</td></tr><tr><td><code>gap</code></td><td>number</td><td>em (<code>1.0</code> = font size 1 em)</td><td>Gap between the fill and stroke</td></tr><tr><td><code>color</code></td><td>color</td><td>RGBA 0–1</td><td>Stroke color</td></tr><tr><td><code>order</code></td><td>string</td><td>—</td><td>Stacking order of fill and stroke. <code>fill_over_stroke</code> / <code>stroke_over_fill</code></td></tr><tr><td><code>join</code></td><td>string</td><td>—</td><td>Join style for stroke corners. <code>miter_clip</code> / <code>round</code> / <code>bevel</code> / <code>miter_round</code> / <code>miter_bevel</code></td></tr><tr><td><code>miter_limit</code></td><td>number</td><td>multiplier</td><td>Maximum length of sharp miter corners</td></tr></tbody></table><p>Characters whose <code>chars[index].stroke.use</code> is <code>false</code> use the Global stroke settings above. For the inheritance order including parts, see <a href="./01_concepts.html#section-inheritance">&quot;Inheritance Mechanism&quot;</a>.</p><h4 id="ctx-global-shadow" tabindex="-1"><code>ctx.global.shadow</code> <a class="header-anchor" href="#ctx-global-shadow" aria-label="Permalink to &quot;`ctx.global.shadow`&quot;">​</a></h4><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>This shadow has <strong>no blur/softness whatsoever</strong>. It is a solid-color copy with sharp outlines, using the same shape as the character or part and merely offset to the position specified by <code>distance</code> / <code>angle</code> (the host has no blur-radius parameter either). Its size is always identical to the original, so at <code>distance = 0</code> it overlaps exactly behind the main text and <strong>the shadow is not visible at all</strong> (it does not become visible through shrinkage or transparency).</p></div><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>boolean</td><td>—</td><td>Whether the Global shadow is enabled</td></tr><tr><td><code>distance</code></td><td>number</td><td>Percentage of the canvas&#39;s shorter side. <code>1.0</code> = 1% of the shorter side (px conversion: <code>distance * min(width, height) / 100</code>). Positive values move away in the <code>angle</code> direction. Maximum on write: <code>10.0</code></td><td>Shadow distance</td></tr><tr><td><code>angle</code></td><td>number</td><td>degree</td><td>Shadow direction. 0 degrees points right, and positive (+) rotates right (clockwise) (90 degrees points straight down)</td></tr><tr><td><code>color</code></td><td>color</td><td>RGBA 0–1</td><td>Shadow color</td></tr></tbody></table><p>Characters whose <code>chars[index].shadow.use</code> is <code>false</code> use <code>shadow.color</code>. For the inheritance order including parts, see <a href="./01_concepts.html#section-inheritance">&quot;Inheritance Mechanism&quot;</a>.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p>Enabling the shadow increases drawing cost and reduces rendering performance. The impact is especially large at high resolutions or with complex text, so use it only when needed.</p></div><p>The gradient fills only areas where both the character and part <code>fill.use</code> values are <code>false</code>. An individual color with <code>fill.use</code> set to <code>true</code> takes precedence over the gradient and becomes a solid color. For the separation of stages between <code>fill.use</code> and <code>opacity</code>, see <a href="./01_concepts.html#section-inheritance">&quot;Inheritance Mechanism&quot;</a>.</p><p><a id="section-camera"></a></p><h3 id="_1-9-ctx-camera" tabindex="-1">1.9 <code>ctx.camera</code> <a class="header-anchor" href="#_1-9-ctx-camera" aria-label="Permalink to &quot;1.9 `ctx.camera`&quot;">​</a></h3><p>The camera for 3D presets. Assignments do not cause errors in 2D presets, but affect rendering only in 3D presets.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>target_x</code> / <code>target_y</code></td><td>number</td><td>canvas normalized coordinate</td><td>Camera look-at point. Positive X is right and positive Y is up. When the look-at point moves, the object appears to move in the opposite direction</td></tr><tr><td><code>yaw</code> / <code>pitch</code></td><td>number</td><td>degree</td><td>Camera orbit. Positive yaw moves the camera around to the right; positive pitch moves it upward (looking down)</td></tr><tr><td><code>perspective</code></td><td>number</td><td>—</td><td>Strength representing camera distance / perspective. Internally mapped to camera distance as <code>distancePx = f(perspective) * canvas.height</code> (<code>f</code> is a monotonic mapping from strength to distance coefficient; larger values move the camera closer and strengthen perspective)</td></tr><tr><td><code>zoom</code></td><td>number</td><td>multiplier</td><td>Projection magnification. Clamped to a minimum of <code>0.001</code> when written</td></tr><tr><td><code>lens_shift_x</code> / <code>lens_shift_y</code></td><td>number</td><td>canvas ratio</td><td>Principal point offset. Positive lens_shift_x shifts everything right; positive lens_shift_y shifts everything up</td></tr></tbody></table><p><a id="section-character"></a></p><h3 id="_1-10-ctx-chars-index" tabindex="-1">1.10 <code>ctx.chars[index]</code> <a class="header-anchor" href="#_1-10-ctx-chars-index" aria-label="Permalink to &quot;1.10 `ctx.chars[index]`&quot;">​</a></h3><p><code>ctx.chars</code> is a <strong>1-based</strong> array, as is standard in Lua. When the text or font changes, the number of characters and the <code>index</code> of each element also change.</p><p>When <code>use</code> for <code>fill</code> / <code>stroke</code> / <code>shadow</code> is <code>false</code>, the setting is not hidden; it inherits the Global value. For details, see <a href="./01_concepts.html#section-inheritance">&quot;Inheritance Mechanism&quot;</a>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>index</code></td><td>integer</td><td>—</td><td>1-based character index. Read-only</td></tr><tr><td><code>text</code></td><td>string</td><td>—</td><td>Original text of this character cluster. Read-only</td></tr><tr><td><code>part_start</code> / <code>part_count</code></td><td>integer</td><td>—</td><td>1-based starting global index and count of owned parts. Read-only</td></tr><tr><td><code>line_index</code></td><td>integer</td><td>—</td><td>1-based index of the line it belongs to. Read-only</td></tr><tr><td><code>geometry</code></td><td>table</td><td>—</td><td>Placement information before transformations (below). Read-only</td></tr><tr><td><code>offset_x</code> / <code>offset_y</code></td><td>number</td><td><a href="./01_concepts.html#section-units">canvas normalized displacement</a></td><td>Character displacement. <code>0.5</code> means displacement 0; larger values move right/up</td></tr><tr><td><code>pivot_x</code> / <code>pivot_y</code></td><td>number</td><td><a href="./01_concepts.html#section-units">canvas normalized displacement</a></td><td>Pivot for character transformations. At <code>0.5</code>, the pivot equals the natural center; larger values move it right/up</td></tr><tr><td><code>scale</code></td><td>number</td><td>multiplier</td><td>Uniform scale. Clamped to a minimum of <code>0.001</code> when written</td></tr><tr><td><code>stretch_x</code> / <code>stretch_y</code></td><td>number</td><td>multiplier</td><td>Nonuniform scale. Unlike scale, it has no positive lower bound; 0 and negative values are accepted</td></tr><tr><td><code>rotation</code></td><td>number</td><td>degree</td><td>2D rotation. Positive (+) is clockwise (right rotation); negative (-) is counterclockwise (left rotation)</td></tr><tr><td><code>z</code></td><td>number</td><td>canvas height ratio</td><td>Depth. Positive (+) moves deeper (away from the camera); negative (-) moves forward (toward the camera). Affects rendering only in 3D presets</td></tr><tr><td><code>yaw</code> / <code>pitch</code></td><td>number</td><td>degree</td><td>Individual 3D rotation. Positive yaw rotates the right edge toward the viewer; positive pitch rotates the top edge toward the viewer. Affects rendering only in 3D presets</td></tr><tr><td><code>opacity</code></td><td>number</td><td>0–1</td><td>Opacity of this character. The default is <code>1.0</code>, and the host clamps out-of-range values immediately before rendering. Multiplied by <code>ctx.global.opacity</code> (does not participate in <code>fill.use</code> resolution. See <a href="./01_concepts.html#section-inheritance">division of roles</a>)</td></tr><tr><td><code>fill</code></td><td>table</td><td>—</td><td>Individual fill (table below)</td></tr><tr><td><code>stroke</code></td><td>table</td><td>—</td><td>Individual stroke (table below)</td></tr><tr><td><code>shadow</code></td><td>table</td><td>—</td><td>Individual shadow color (table below)</td></tr></tbody></table><h4 id="chars-index-fill" tabindex="-1"><code>chars[index].fill</code> <a class="header-anchor" href="#chars-index-fill" aria-label="Permalink to &quot;`chars[index].fill`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>use</code></td><td>boolean</td><td>—</td><td>When <code>true</code>, uses <code>fill.color</code></td></tr><tr><td><code>color</code></td><td>color</td><td>RGBA 0–1</td><td>Individual color used when <code>use</code> is <code>true</code></td></tr></tbody></table><h4 id="chars-index-stroke" tabindex="-1"><code>chars[index].stroke</code> <a class="header-anchor" href="#chars-index-stroke" aria-label="Permalink to &quot;`chars[index].stroke`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>use</code></td><td>boolean</td><td>—</td><td>When <code>true</code>, uses <code>stroke.width</code> / <code>stroke.gap</code> / <code>stroke.color</code></td></tr><tr><td><code>width</code></td><td>number</td><td>em (<code>1.0</code> = font size 1 em)</td><td>Used when <code>use</code> is <code>true</code></td></tr><tr><td><code>gap</code></td><td>number</td><td>em (<code>1.0</code> = font size 1 em)</td><td>Used when <code>use</code> is <code>true</code></td></tr><tr><td><code>color</code></td><td>color</td><td>RGBA 0–1</td><td>Used when <code>use</code> is <code>true</code></td></tr></tbody></table><h4 id="chars-index-shadow" tabindex="-1"><code>chars[index].shadow</code> <a class="header-anchor" href="#chars-index-shadow" aria-label="Permalink to &quot;`chars[index].shadow`&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>use</code></td><td>boolean</td><td>—</td><td>When <code>true</code>, uses <code>shadow.color</code></td></tr><tr><td><code>color</code></td><td>color</td><td>RGBA 0–1</td><td>Individual color used when <code>use</code> is <code>true</code></td></tr></tbody></table><p>Assigning an entire table to a subobject follows the same merge rules as §1.8.</p><h4 id="chars-index-geometry" tabindex="-1"><code>chars[index].geometry</code> <a class="header-anchor" href="#chars-index-geometry" aria-label="Permalink to &quot;`chars[index].geometry`&quot;">​</a></h4><p>Represents the layout from <strong>before</strong> character script transformations, Deform, and 3D projection.</p><p>Positions and dimensions use <a href="./01_concepts.html#section-units">canvas normalization</a>. Internal pixel coordinates are converted with X as <code>0.5 + px/width</code> and Y as <code>0.5 - px/height</code>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>canvas_origin_x</code> / <code>canvas_origin_y</code></td><td>number</td><td>canvas normalized coordinate</td><td>Typesetting origin (horizontal writing: placement origin corresponding to the cell&#39;s left edge × baseline)</td></tr><tr><td><code>vertical_origin_x</code> / <code>vertical_origin_y</code></td><td>number</td><td>canvas normalized coordinate</td><td>Vertical-typesetting origin (column center axis × cell top)</td></tr><tr><td><code>bounds_center_x</code> / <code>bounds_center_y</code></td><td>number</td><td>canvas normalized coordinate</td><td>Center of the area occupied by the character outline before transformations (ink bounds)</td></tr><tr><td><code>bounds_width</code></td><td>number</td><td>canvas width ratio</td><td>Ink bounds width / canvas width</td></tr><tr><td><code>bounds_height</code></td><td>number</td><td>canvas height ratio</td><td>Ink bounds height / canvas height</td></tr><tr><td><code>advance_x</code></td><td>number</td><td>canvas width ratio</td><td>Font horizontal advance (px) / canvas width. <strong>Does not include tracking / margins</strong></td></tr><tr><td><code>advance_y</code></td><td>number</td><td>canvas height ratio</td><td>Font vertical advance (px) / canvas height (sign-inverted to Y-up). Downward advance is negative. <strong>Does not include tracking / margins</strong></td></tr></tbody></table><p><a id="section-part"></a></p><h3 id="_1-11-ctx-parts-index" tabindex="-1">1.11 <code>ctx.parts[index]</code> <a class="header-anchor" href="#_1-11-ctx-parts-index" aria-label="Permalink to &quot;1.11 `ctx.parts[index]`&quot;">​</a></h3><p><code>ctx.parts</code> is a <strong>1-based</strong> array, as is standard in Lua. <code>index</code> is not a number within each character, but a part number across the entire frame. When the text or font changes, the number of parts and the <code>index</code> of each element also change.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>index</code></td><td>integer</td><td>—</td><td>1-based global part index. Read-only</td></tr><tr><td><code>character_index</code></td><td>integer</td><td>—</td><td>1-based index of the owning character. Read-only</td></tr><tr><td><code>index_in_character</code></td><td>integer</td><td>—</td><td>1-based part index within the character. Read-only</td></tr><tr><td><code>geometry</code></td><td>table</td><td>—</td><td>Placement information before transformations (table below). Read-only</td></tr><tr><td><code>offset_x</code> / <code>offset_y</code></td><td>number</td><td><a href="./01_concepts.html#section-units">canvas normalized displacement</a></td><td>Part displacement. <code>0.5</code> means displacement 0; larger values move right/up</td></tr><tr><td><code>pivot_x</code> / <code>pivot_y</code></td><td>number</td><td><a href="./01_concepts.html#section-units">canvas normalized displacement</a></td><td>Pivot for part transformations. At <code>0.5</code>, the pivot equals the natural position; larger values move it right/up</td></tr><tr><td><code>scale</code></td><td>number</td><td>multiplier</td><td>Uniform scale. Clamped to a minimum of <code>0.001</code> when written</td></tr><tr><td><code>rotation</code></td><td>number</td><td>degree</td><td>2D rotation. Positive (+) is clockwise (right rotation); negative (-) is counterclockwise (left rotation)</td></tr><tr><td><code>stretch_x</code> / <code>stretch_y</code></td><td>number</td><td>multiplier</td><td>Nonuniform scale. Unlike scale, it has no positive lower bound; 0 and negative values are accepted</td></tr><tr><td><code>z</code></td><td>number</td><td>canvas height ratio</td><td>Depth. Positive (+) moves deeper (away from the camera); negative (-) moves forward (toward the camera). Affects rendering only in 3D presets</td></tr><tr><td><code>yaw</code> / <code>pitch</code></td><td>number</td><td>degree</td><td>Individual 3D rotation of the part. Applied around the part pivot inside the owning character&#39;s rotated space. Positive yaw rotates the right edge toward the viewer; positive pitch rotates the top edge toward the viewer. Affects rendering only in 3D presets</td></tr><tr><td><code>opacity</code></td><td>number</td><td>0–1</td><td>Opacity of this part. The default is <code>1.0</code>, and the host clamps out-of-range values immediately before rendering. Multiplied by the owning character&#39;s <code>opacity</code> (and further by <code>ctx.global.opacity</code>) (does not participate in <code>fill.use</code> resolution. See <a href="./01_concepts.html#section-inheritance">division of roles</a>)</td></tr><tr><td><code>fill</code></td><td>table</td><td>—</td><td>Individual fill with <code>use</code> / <code>color</code>. Has the same structure as the character&#39;s <code>fill</code>; when <code>use</code> is <code>true</code>, uses <code>color</code></td></tr><tr><td><code>stroke</code></td><td>table</td><td>—</td><td>Individual stroke with <code>use</code> / <code>width</code> / <code>gap</code> / <code>color</code>. Has the same structure as the character&#39;s <code>stroke</code>; when <code>use</code> is <code>true</code>, uses the individual values</td></tr><tr><td><code>shadow</code></td><td>table</td><td>—</td><td>Individual shadow color with <code>use</code> / <code>color</code>. Has the same structure as the character&#39;s <code>shadow</code>; when <code>use</code> is <code>true</code>, uses <code>color</code></td></tr></tbody></table><h4 id="inheritance-from-the-character" tabindex="-1">Inheritance from the Character <a class="header-anchor" href="#inheritance-from-the-character" aria-label="Permalink to &quot;Inheritance from the Character&quot;">​</a></h4><p>A part&#39;s fill, stroke, and shadow are determined by their respective <code>use</code> values as follows.</p><table tabindex="0"><thead><tr><th>Part Setting</th><th><code>use = false</code></th><th><code>use = true</code></th></tr></thead><tbody><tr><td><code>fill</code></td><td>Inherits the fill selected at the owning character level</td><td>Uses the part&#39;s <code>fill.color</code></td></tr><tr><td><code>stroke</code></td><td>Inherits the <code>width</code> / <code>gap</code> / <code>color</code> selected at the owning character level</td><td>Uses the part&#39;s <code>stroke</code> settings</td></tr><tr><td><code>shadow</code></td><td>Inherits the <code>shadow.color</code> selected at the owning character level</td><td>Uses the part&#39;s <code>shadow.color</code></td></tr></tbody></table><p>If <code>use = false</code> on the owning character as well, resolution continues up to the <code>ctx.global</code> settings. For details, see <a href="./01_concepts.html#section-inheritance">&quot;Inheritance Mechanism&quot;</a>.</p><h4 id="individual-settings-not-in-the-inspector" tabindex="-1">Individual Settings Not in the Inspector <a class="header-anchor" href="#individual-settings-not-in-the-inspector" aria-label="Permalink to &quot;Individual Settings Not in the Inspector&quot;">​</a></h4><p>There are no parameters for a part&#39;s <code>stroke</code> and <code>shadow</code> in the Inspector, so they begin unused/with default values. When a script sets <code>use</code> to <code>true</code>, the configured individual values take precedence.</p><p>There are also no <code>yaw</code> / <code>pitch</code> parameters in the Inspector, and their initial values are <code>0</code>. They are independent of the owning character&#39;s rotation and are applied as additional rotation within the character&#39;s rotation space.</p><h4 id="parts-index-geometry" tabindex="-1"><code>parts[index].geometry</code> <a class="header-anchor" href="#parts-index-geometry" aria-label="Permalink to &quot;`parts[index].geometry`&quot;">​</a></h4><p>Represents the layout before script transformations, Deform, and 3D projection. Positive Y is up.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>local_center_x</code> / <code>local_center_y</code></td><td>number</td><td>displacement in canvas-axis ratios</td><td>Part center relative to the owning character&#39;s pre-transformation outline bounds (ink bounds) center as the origin. No neutral offset (<code>0</code> is at the character center). The Y component is Y-up</td></tr><tr><td><code>canvas_center_x</code> / <code>canvas_center_y</code></td><td>number</td><td>canvas normalized coordinate</td><td>Canvas coordinates of the part&#39;s natural position (center after layout)</td></tr><tr><td><code>bounds_center_x</code> / <code>bounds_center_y</code></td><td>number</td><td>canvas normalized coordinate</td><td>Center of the area occupied by the part outline before transformations (ink bounds)</td></tr><tr><td><code>bounds_width</code> / <code>bounds_height</code></td><td>number</td><td>respective canvas-axis ratios</td><td>Width and height of the ink bounds</td></tr></tbody></table><p><a id="section-bounding-box"></a></p><h3 id="_1-12-ctx-bounding-box" tabindex="-1">1.12 <code>ctx.bounding_box</code> <a class="header-anchor" href="#_1-12-ctx-bounding-box" aria-label="Permalink to &quot;1.12 `ctx.bounding_box`&quot;">​</a></h3><h4 id="base-rectangle" tabindex="-1">Base Rectangle <a class="header-anchor" href="#base-rectangle" aria-label="Permalink to &quot;Base Rectangle&quot;">​</a></h4><p>The base rectangle is the union of the bounds after part matrices are applied. Under 3D projection, the projected paths are used. Margins are added outside it, and fill and stroke are each drawn with independent offsets.</p><h4 id="dimension-reference" tabindex="-1">Dimension Reference <a class="header-anchor" href="#dimension-reference" aria-label="Permalink to &quot;Dimension Reference&quot;">​</a></h4><p>The following dimensional fields are <strong>percentages of fontSize</strong> (rendering: <code>value * fontSizePx / 100</code>; <code>100.0</code> = the same length as fontSize).</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>boolean</td><td>—</td><td>Enables drawing the frame</td></tr><tr><td><code>draw_top</code> / <code>draw_bottom</code> / <code>draw_left</code> / <code>draw_right</code></td><td>boolean</td><td>—</td><td>Whether to draw the stroke on each side</td></tr><tr><td><code>color</code></td><td>color</td><td>RGBA 0–1</td><td>Frame line color</td></tr><tr><td><code>width</code></td><td>number</td><td>fontSize percentage</td><td>Frame line thickness</td></tr><tr><td><code>fill_enabled</code></td><td>boolean</td><td>—</td><td>Enables filling inside the frame</td></tr><tr><td><code>fill_color</code></td><td>color</td><td>RGBA 0–1</td><td>Interior fill color (its alpha is multiplied by <code>fill_opacity</code>)</td></tr><tr><td><code>fill_opacity</code></td><td>number</td><td>0–1</td><td>Opacity multiplier for the interior fill</td></tr><tr><td><code>start_cap</code> / <code>end_cap</code></td><td>string</td><td>enumeration below</td><td>Caps for open path endpoints</td></tr><tr><td><code>margin_x</code> / <code>margin_y</code></td><td>number</td><td>fontSize percentage</td><td>Margin outside the text bounds (added to each side)</td></tr><tr><td><code>corner_radius</code></td><td>number</td><td>fontSize percentage</td><td>Corner radius when all four sides are enabled (capped at half the rectangle size)</td></tr><tr><td><code>fill_offset_x</code> / <code>fill_offset_y</code></td><td>number</td><td>fontSize percentage</td><td>Translation of the fill rectangle. Positive X is right. <strong>Y uses drawing space (Y-down), so positive values move downward</strong> (opposite in sign to the Y-up <code>offset_y</code>)</td></tr><tr><td><code>stroke_offset_x</code> / <code>stroke_offset_y</code></td><td>number</td><td>fontSize percentage</td><td>Translation of the frame line (independent of the fill. The sign of Y is the same as <code>fill_offset_*</code>)</td></tr></tbody></table><p>Values of <code>start_cap</code> / <code>end_cap</code>: <code>butt</code> / <code>square</code> / <code>round</code> / <code>round_rev</code> / <code>triangle</code> / <code>triangle_rev</code></p><p><a id="section-output"></a></p><h3 id="_1-13-ctx-output" tabindex="-1">1.13 <code>ctx.output</code> <a class="header-anchor" href="#_1-13-ctx-output" aria-label="Permalink to &quot;1.13 `ctx.output`&quot;">​</a></h3><p>Output filtering and drawing-order controls read and written in <code>OnLayout</code>. Separation-related fields are read-only.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>separation_enabled</code></td><td>boolean</td><td>—</td><td>Whether Separation output is enabled. Read-only</td></tr><tr><td><code>render_mode</code></td><td>string</td><td>—</td><td>Current output slot. <code>default</code> / <code>separation_1</code> / <code>separation_2</code>. Read-only</td></tr><tr><td><code>targets_1</code> / <code>targets_2</code></td><td>string</td><td>—</td><td>Target specification string assigned to each Separation output. Read-only</td></tr><tr><td><code>write_on_mode</code></td><td>string</td><td>—</td><td>Write-on unit. <code>character</code> or <code>part</code></td></tr><tr><td><code>write_on_start</code></td><td>number</td><td>0–1</td><td>Start of the visible interval (normalized progress)</td></tr><tr><td><code>write_on_end</code></td><td>number</td><td>0–1</td><td>End of the visible interval. No filter (everything visible) when <code>start = 0</code> and <code>end = 1</code></td></tr><tr><td><code>reorder_parts</code></td><td>boolean</td><td>—</td><td>When <code>true</code>, uses writing order (stroke order) for part drawing order and reveal order. Has no visual effect on single-part characters</td></tr><tr><td><code>manual_order_enabled</code></td><td>boolean</td><td>—</td><td>When <code>true</code>, overrides reveal / drawing order with <code>manual_order_text</code></td></tr><tr><td><code>manual_order_text</code></td><td>string</td><td>—</td><td>Manual order specification (syntax below)</td></tr></tbody></table><h4 id="write-on" tabindex="-1">Write-on <a class="header-anchor" href="#write-on" aria-label="Permalink to &quot;Write-on&quot;">​</a></h4><p>Visible elements are limited to those whose <strong>1-based rank</strong> within the unit lies in <code>[startLimit, endLimit]</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>startLimit = floor(write_on_start * N) + 1</span></span>\n<span class="line"><span>endLimit   = ceil(write_on_end * N)</span></span></code></pre></div><p><code>N</code> is the number of characters when <code>write_on_mode == &quot;character&quot;</code> and the number of parts when it is <code>&quot;part&quot;</code>.</p><p>How ranks are determined:</p><table tabindex="0"><thead><tr><th>mode</th><th>Default Rank</th><th>When <code>manual_order_enabled</code></th><th><code>reorder_parts</code> Only</th></tr></thead><tbody><tr><td><code>character</code></td><td>Character index in layout order (1..N)</td><td>Character-level manual reveal order</td><td>Character rank remains in layout order</td></tr><tr><td><code>part</code></td><td><code>ctx.parts[index].index</code> (1..N)</td><td>Manual reveal order of parts</td><td>Reveal order in stroke order</td></tr></tbody></table><h4 id="manual-order-text-syntax" tabindex="-1"><code>manual_order_text</code> Syntax <a class="header-anchor" href="#manual-order-text-syntax" aria-label="Permalink to &quot;`manual_order_text` Syntax&quot;">​</a></h4><h5 id="token-interpretation" tabindex="-1">Token Interpretation <a class="header-anchor" href="#token-interpretation" aria-label="Permalink to &quot;Token Interpretation&quot;">​</a></h5><p>Tokens are separated by commas or spaces. Invalid tokens are ignored, and if the same part is specified multiple times, only the first specification is used.</p><table tabindex="0"><thead><tr><th>Token</th><th>Meaning</th></tr></thead><tbody><tr><td><code>c&lt;n&gt;</code> / <code>C&lt;n&gt;</code></td><td>1-based character n. Expands all parts of that character in the part order in effect at the time (<code>reorder_parts</code> true uses stroke order; false uses layout order)</td></tr><tr><td><code>p&lt;n&gt;</code> / <code>P&lt;n&gt;</code></td><td>1-based global part n</td></tr><tr><td><code>&lt;n&gt;</code></td><td>No prefix. Interpreted as a part index</td></tr><tr><td><code>&lt;a&gt;-&lt;b&gt;</code></td><td>Inclusive range. Both endpoints must be of the same type (both characters or both parts). If only one endpoint has a prefix, the other inherits its type. Expands in ascending order</td></tr></tbody></table><p>Examples: <code>&quot;3,1,2&quot;</code> (parts 3→1→2), <code>&quot;c1-c3&quot;</code> (characters 1–3), <code>&quot;p2-p5&quot;</code> (parts 2–5).</p><h5 id="effect-on-ordering" tabindex="-1">Effect on Ordering <a class="header-anchor" href="#effect-on-ordering" aria-label="Permalink to &quot;Effect on Ordering&quot;">​</a></h5><p>Specified elements are moved to the front in the specified order. <strong>Unlisted parts are not hidden</strong>; they follow afterward while preserving their relative order from the base ordering.</p><p>The order is determined from the undeformed layout and the specification string; it is not recomputed each frame from spatial positions after animation. <code>write_on_start/end</code> determines the visible range, while manual order changes only the order of elements.</p><p><a id="section-path-context"></a></p><h3 id="_1-14-ctx-paths" tabindex="-1">1.14 <code>ctx.paths</code> <a class="header-anchor" href="#_1-14-ctx-paths" aria-label="Permalink to &quot;1.14 `ctx.paths`&quot;">​</a></h3><p>Because <code>ctx.paths</code> retrieves targets lazily, paths for parts that are not retrieved are not copied to the Lua side.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>units_per_em</code></td><td>number</td><td>path unit/em</td><td>Path coordinate scale. Always <code>1000</code></td></tr><tr><td><code>part(index)</code></td><td>function</td><td>—</td><td>Retrieves 1 part by its 1-based global part number. Returns <code>nil</code> if it does not exist</td></tr><tr><td><code>character(index)</code></td><td>function</td><td>—</td><td>Retrieves all parts owned by the 1-based character number as an array ordered by global part number</td></tr><tr><td><code>select(selector)</code></td><td>function</td><td>—</td><td>Retrieves parts matching the selection syntax as an array ordered by global part number</td></tr></tbody></table><h4 id="selection-syntax-for-select-selector" tabindex="-1">Selection Syntax for <code>select(selector)</code> <a class="header-anchor" href="#selection-syntax-for-select-selector" aria-label="Permalink to &quot;Selection Syntax for `select(selector)`&quot;">​</a></h4><p><code>c</code> denotes a character number, <code>p</code> denotes a global part number, and <code>!</code> denotes exclusion. Multiple conditions can be specified with commas, and ranges such as <code>c3-5</code> and <code>p8-10</code> are supported.</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> parts </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ctx.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paths</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">select</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;c1, p8-10, !p9&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>When the same part is retrieved multiple times, the same mutable object is returned within a frame.</p><h4 id="retrieved-parts" tabindex="-1">Retrieved Parts <a class="header-anchor" href="#retrieved-parts" aria-label="Permalink to &quot;Retrieved Parts&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Unit</th><th>Description</th></tr></thead><tbody><tr><td><code>index</code></td><td>integer</td><td>—</td><td>1-based global part number across the frame</td></tr><tr><td><code>character_index</code></td><td>integer</td><td>—</td><td>1-based number of the character it belongs to</td></tr><tr><td><code>index_in_character</code></td><td>integer</td><td>—</td><td>1-based part number within the character it belongs to</td></tr><tr><td><code>line_index</code></td><td>integer</td><td>—</td><td>1-based number of the line it belongs to</td></tr><tr><td><code>text</code></td><td>string</td><td>—</td><td>Text represented by the character it belongs to</td></tr><tr><td><code>path</code></td><td>path</td><td>—</td><td>Drawing path to modify</td></tr></tbody></table><h4 id="editing-path" tabindex="-1">Editing <code>path</code> <a class="header-anchor" href="#editing-path" aria-label="Permalink to &quot;Editing `path`&quot;">​</a></h4><p><code>path</code> is a mutable object representing the part&#39;s drawing outline. You can clear or replace the original outline and add straight lines or Bézier curves. For details on the methods and coordinate system, see <a href="./03_mt_reference.html#api-drawing-path">Drawing Path Editing API</a>.</p>',149)])])}const u=e(i,[["render",r]]);export{g as __pageData,u as default};
